import { Component, OnInit } from "@angular/core";
import { ProductService } from "../../services/product.service";
import { CartService } from "../../services/cart.service";
import { AuthService } from "../../services/auth.service";
import { Product } from "../../models/product";
import { Router } from "@angular/router";

@Component({
  selector: "app-product-list",
  templateUrl: "./product-list.component.html",
  styleUrls: ["./product-list.component.css"],
})
export class ProductListComponent implements OnInit {
  Math = Math;
  allProducts: Product[] = [];
  filteredProducts: Product[] = [];
  pagedProducts: Product[] = [];
  categories: string[] = [];
  selectedCategory = "All";
  searchTerm = "";
  addedProductId: number | null = null;

  // Pagination
  currentPage = 1;
  pageSize = 12;
  totalPages = 1;
  pages: number[] = [];

  constructor(
    private productService: ProductService,
    public cart: CartService,
    public auth: AuthService,
    private router: Router,
  ) {}

  ngOnInit(): void {
    this.productService.getProducts().subscribe((products) => {
      this.allProducts = products;
      this.categories = ["All", ...new Set(products.map((p) => p.category))];
      this.applyFilters();
    });
  }

  applyFilters(): void {
    this.filteredProducts = this.allProducts.filter((p) => {
      const matchCat =
        this.selectedCategory === "All" || p.category === this.selectedCategory;
      const matchSearch =
        p.name.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
        p.description.toLowerCase().includes(this.searchTerm.toLowerCase());
      return matchCat && matchSearch;
    });
    this.currentPage = 1;
    this.updatePagination();
  }

  updatePagination(): void {
    this.totalPages = Math.ceil(this.filteredProducts.length / this.pageSize);
    this.pages = Array.from({ length: this.totalPages }, (_, i) => i + 1);
    this.setPage(this.currentPage);
  }

  setPage(page: number): void {
    if (page < 1 || page > this.totalPages) return;
    this.currentPage = page;
    const start = (page - 1) * this.pageSize;
    this.pagedProducts = this.filteredProducts.slice(
      start,
      start + this.pageSize,
    );
    window.scrollTo({ top: 0, behavior: "smooth" });
  }

  selectCategory(cat: string): void {
    this.selectedCategory = cat;
    this.applyFilters();
  }

  onSearch(): void {
    this.applyFilters();
  }

  addToCart(product: Product): void {
    if (!this.auth.isLoggedIn) {
      this.router.navigate(["/login"]);
      return;
    }
    this.cart.addToCart(product);
    this.addedProductId = product.id;
    setTimeout(() => (this.addedProductId = null), 1500);
  }

  viewDetails(id: number): void {
    this.router.navigate(["/products", id]);
  }

  getVisiblePages(): number[] {
    const delta = 2;
    const range: number[] = [];
    for (
      let i = Math.max(2, this.currentPage - delta);
      i <= Math.min(this.totalPages - 1, this.currentPage + delta);
      i++
    ) {
      range.push(i);
    }
    if (this.currentPage - delta > 2) range.unshift(-1);
    if (this.currentPage + delta < this.totalPages - 1) range.push(-1);
    if (this.totalPages > 1) range.unshift(1);
    if (this.totalPages > 1) range.push(this.totalPages);
    return [...new Set(range)];
  }
}
<div class="product-page">
  <div class="page-header">
    <h1>Our Products</h1>
    <p>
      Discover {{ filteredProducts.length }} amazing products at great prices
    </p>
  </div>

  <div class="filters">
    <div class="search-box">
      <input
        type="text"
        placeholder="Search products..."
        [(ngModel)]="searchTerm"
        (input)="onSearch()"
        class="search-input"
      />
      <span class="search-icon">🔍</span>
    </div>
    <div class="category-tabs">
      <button
        *ngFor="let cat of categories"
        [class.active]="selectedCategory === cat"
        (click)="selectCategory(cat)"
        class="cat-btn"
      >
        {{ cat }}
      </button>
    </div>
  </div>

  <div class="results-info">
    Showing {{ (currentPage - 1) * 12 + 1 }}–{{
      Math.min(currentPage * 12, filteredProducts.length)
    }}
    of {{ filteredProducts.length }} products
  </div>

  <div class="products-grid" *ngIf="pagedProducts.length > 0; else noProducts">
    <div class="product-card" *ngFor="let product of pagedProducts">
      <div class="product-img-wrap" (click)="viewDetails(product.id)">
        <img
          [src]="product.imageUrl"
          [alt]="product.name"
          class="product-img"
          loading="lazy"
        />
        <span class="product-category">{{ product.category }}</span>
        <span class="out-of-stock-overlay" *ngIf="product.stock === 0"
          >Out of Stock</span
        >
      </div>
      <div class="product-info">
        <h3 class="product-name" (click)="viewDetails(product.id)">
          {{ product.name }}
        </h3>
        <p class="product-desc">{{ product.description | slice: 0 : 75 }}...</p>
        <div class="product-footer">
          <span class="product-price">₹{{ product.price | number }}</span>
          <span
            class="stock-badge"
            [class.low]="product.stock > 0 && product.stock < 5"
            [class.out]="product.stock === 0"
          >
            {{
              product.stock === 0
                ? "Out of Stock"
                : product.stock < 5
                  ? "Only " + product.stock + " left"
                  : "In Stock"
            }}
          </span>
        </div>
        <button
          class="add-to-cart-btn"
          [class.added]="addedProductId === product.id"
          (click)="addToCart(product)"
          [disabled]="product.stock === 0"
        >
          {{ addedProductId === product.id ? "✓ Added!" : "🛒 Add to Cart" }}
        </button>
      </div>
    </div>
  </div>

  <!-- Pagination -->
  <div class="pagination" *ngIf="totalPages > 1">
    <button
      class="page-btn nav"
      (click)="setPage(currentPage - 1)"
      [disabled]="currentPage === 1"
    >
      ‹ Prev
    </button>
    <ng-container *ngFor="let p of getVisiblePages()">
      <span *ngIf="p === -1" class="page-dots">...</span>
      <button
        *ngIf="p !== -1"
        class="page-btn"
        [class.active]="p === currentPage"
        (click)="setPage(p)"
      >
        {{ p }}
      </button>
    </ng-container>
    <button
      class="page-btn nav"
      (click)="setPage(currentPage + 1)"
      [disabled]="currentPage === totalPages"
    >
      Next ›
    </button>
  </div>

  <ng-template #noProducts>
    <div class="no-products">
      <div class="no-products-icon">😕</div>
      <p>No products found. Try a different search or category.</p>
      <button
        class="reset-btn"
        (click)="searchTerm = ''; selectedCategory = 'All'; applyFilters()"
      >
        Clear Filters
      </button>
    </div>
  </ng-template>
</div>
